Object.assign(window.deepArticles, {
  "lamotrek":westernIslandArticle({
    title:"Lamotrek",infoboxKicker:"Atoll of the Yap outer islands",
    lead:"Lamotrek is a small coral atoll in the central Caroline Islands and part of the Japanese Yap district. Its three principal islets, compact lagoon, limited freshwater, canoe routes, chiefly institutions, and Lamotrekese-speaking community make it a distinct island society within the wider Woleaian cultural region. Lamotrek is also an ancestral source of the Refaluwasch community in the northern Marianas.",
    canon:"Lamotrek's geography, three-islet form, chiefly organization, navigation, storm vulnerability, relationship with Woleai, and migration toward Saipan are historical. Continuous Japanese administration and nationality follow setting canon. Exact 1985 population, officeholders, harbor works, air service, and municipal organization remain open.",
    sections:[
      {id:"geography",title:"Geography",html:"<p>Lamotrek is a low coral atoll formed by three principal islets around a small lagoon. Reef passages, wells, taro pits, breadfruit land, coconut stands, and canoe beaches define the inhabited landscape.</p>"},
      {id:"settlement",title:"Settlement and subsistence",html:"<p>Households combine gardening, reef fishing, pelagic fishing, food preservation, copra, and reciprocal exchange. Scarce land and freshwater require detailed rights and shared work.</p>"},
      {id:"authority",title:"Island authority",html:"<p>Chiefs, lineage elders, and household leaders coordinate land, labor, exchange, dispute settlement, and external relations. Moral pressure, reputation, sharing, and controlled anger support social order in a small face-to-face community.</p>"},
      {id:"navigation",title:"Navigation network",html:"<p>Lamotrekese sailors maintain routes to Woleai, Satawal, Puluwat, Yap, and the Marianas. Star courses, swell reading, canoe construction, and kinship make the sea a connected geography rather than a boundary.</p>"},
      {id:"marianas",title:"Migration toward Saipan",html:"<p>Storms and scarcity encouraged nineteenth-century families from Lamotrek and neighboring atolls to settle in the northern Marianas. Their descendants became part of the <a href='carolinian-people-marianas.html'>Refaluwasch people</a>.</p>"},
      {id:"colonial",title:"Japanese administration",html:"<p>Spanish claims and German rule preceded Japanese administration from 1914. Schools, medical visits, copra purchasing, surveys, shipping, and district law connected Lamotrek to Yap without creating a large settler town.</p>"},
      {id:"storms",title:"Storms and recovery",html:"<p>Typhoons can destroy houses, gardens, canoes, wells, and entire shorelines within hours. Recovery depends on stored food, inter-island aid, Japanese shipping, migration, and the reallocation of collective labor.</p>"},
      {id:"1985",title:"Lamotrek in 1985",html:"<p>By 1985 Lamotrek is an incorporated Japanese island whose residents possess national citizenship. Local language, chiefs, clan and household rights, navigation, church life, and Marianas kinship remain more immediate than distant metropolitan identity.</p>"}
    ],
    related:[{href:"lamotrekese-people.html",kicker:"Island community",label:"Lamotrekese People"},{href:"lamotrekese-language.html",kicker:"Island language",label:"Lamotrekese Language"},{href:"yap-islands.html",kicker:"Administrative district",label:"Yap Islands"},{href:"woleaian-people.html",kicker:"Closest cultural region",label:"Woleaian People"},{href:"satawalese-people.html",kicker:"Voyaging neighbor",label:"Satawalese People"},{href:"carolinian-people-marianas.html",kicker:"Migrant descendants",label:"Carolinian People of the Marianas"}],
    facts:[["Island type","Coral atoll"],["Principal islets","Three"],["Region","Central Caroline Islands"],["Japanese district","Yap"],["Indigenous community","Lamotrekese"],["Language","Lamotrekese"],["Historic migrant destination","Saipan"],["Nationality in 1985","Japanese"]],
    sources:[{href:"https://en.wikipedia.org/wiki/Lamotrek",label:"Geographic reference — Lamotrek Atoll"},{href:"https://www.wikidata.org/wiki/Q137499714",label:"Ethnographic reference — Lamotrek and inter-island ties"},{href:"https://nach.gov.fm/wp-content/uploads/2019/01/riesenberg-1972-the-organization-of-navigational-knowledge-on-puluwat-1.pdf",label:"FSM National Archives — Lamotrek in the navigational network"}]
  }),
  "lamotrekese-people":westernIslandArticle({
    title:"Lamotrekese people",category:"Peoples of Imperial Japan",eyebrow:"Outer-island society · Empire of Japan",infoboxKicker:"Indigenous people of Lamotrek",
    lead:"The Lamotrekese people are the indigenous people of Lamotrek Atoll in the Yap outer islands. They share the wider Woleaian cultural and linguistic continuum while maintaining their own island ancestry, speech, chiefs, land, reef rights, navigation routes, and migration history. Lamotrekese voyagers were among the ancestors of the Refaluwasch people of Saipan.",
    canon:"Lamotrekese identity, chiefly and kinship organization, navigation, relationship to Woleai and Satawal, nineteenth-century Marianas migration, and storm adaptation are historical. Japanese nationality follows setting canon. Exact 1985 population, chiefs, clan structure, and diaspora totals remain open.",
    sections:[
      {id:"homeland",title:"Atoll homeland",html:"<p>Lamotrekese society is rooted in a compact atoll where land, reef, wells, canoe beaches, gardens, and lagoon passages carry inherited rights. Residence elsewhere does not automatically end those obligations.</p>"},
      {id:"kinship",title:"Kinship and authority",html:"<p>Lineages, households, adoption, marriage, seniority, and chiefs distribute work and resources. Social standing joins inherited position to generosity, competence, and fulfillment of communal obligations.</p>"},
      {id:"subsistence",title:"Food and exchange",html:"<p>Breadfruit, taro, coconut, reef catch, pelagic fish, preserved foods, and copra support households. Formal and informal exchange spreads risk across families and islands.</p>"},
      {id:"navigation",title:"Voyaging tradition",html:"<p>Navigators learn stars, swells, winds, birds, reefs, canoe behavior, and named routes. Lamotrek's location makes knowledge of Woleai, Satawal, Puluwat, and the Marianas central to community history.</p>"},
      {id:"refaluwasch",title:"Refaluwasch ancestry",html:"<p>Lamotrekese families moved toward Saipan during the nineteenth century after storms and shortages. Their descendants joined other central-Caroline migrants in forming Refaluwasch society and language.</p>"},
      {id:"church",title:"Church and colonial life",html:"<p>Christian worship, Japanese schools, copra trade, health visits, and district administration changed daily life. Local authority, language, food exchange, and canoe knowledge continued beneath those institutions.</p>"},
      {id:"diaspora",title:"Migration and return",html:"<p>Students and workers live on Yap, Saipan, Koror, and in Japan. Remittances, funerals, marriage, church ties, language, and return voyages preserve membership in a dispersed community.</p>"},
      {id:"1985",title:"Lamotrekese identity in 1985",html:"<p>By 1985 Lamotrekese are Japanese citizens and a distinct island people within the Yap district. Their identity is neither simply Woleaian nor merely an ancestral component of Saipan Carolinian society.</p>"}
    ],
    related:[{href:"lamotrek.html",kicker:"Island homeland",label:"Lamotrek"},{href:"lamotrekese-language.html",kicker:"Community speech",label:"Lamotrekese Language"},{href:"woleaian-people.html",kicker:"Closest cultural neighbors",label:"Woleaian People"},{href:"satawalese-people.html",kicker:"Voyaging neighbors",label:"Satawalese People"},{href:"carolinian-people-marianas.html",kicker:"Migrant descendants",label:"Carolinian People of the Marianas"},{href:"micronesian-peoples.html",kicker:"Regional comparison",label:"Micronesian Peoples"}],
    facts:[["Homeland","Lamotrek Atoll"],["Administrative region","Yap outer islands"],["Language","Lamotrekese"],["Broader cultural continuum","Woleaian"],["Major heritage","Ocean navigation"],["Historic migrant destination","Saipan"],["Principal public language","Japanese"],["Nationality in 1985","Japanese"]],
    sources:[{href:"https://en.wikipedia.org/wiki/Lamotrek",label:"Geographic and community reference — Lamotrek"},{href:"https://www.wikidata.org/wiki/Q137499714",label:"William Alkire — Lamotrek inter-island socioeconomic ties"}]
  }),
  "lamotrekese-language":westernIslandArticle({
    title:"Lamotrekese language",category:"Languages",eyebrow:"Chuukic variety · Lamotrek Atoll",infoboxKicker:"Traditional language of Lamotrek",
    lead:"Lamotrekese is the traditional Chuukic speech of Lamotrek Atoll. Linguists often classify it within the Woleaian language or a closely connected dialect chain, while islanders recognize it as the speech of a distinct community. It also contributed to the formation of Saipan Carolinian through nineteenth-century migration.",
    canon:"Lamotrekese's place in the Woleaian continuum, relation to Satawalese and Carolinian, navigation vocabulary, and small speaker base are historical. Continuous Japanese public dominance follows setting canon. Exact 1985 speaker totals, language-versus-dialect recognition, orthography, and school provision remain open.",
    sections:[
      {id:"classification",title:"Classification",html:"<p>Lamotrekese belongs to the Chuukic branch of Nuclear Micronesian. It is usually placed with Woleaian but shares features across the central-Caroline continuum.</p>"},
      {id:"status",title:"Language or variety",html:"<p>Structural similarity supports treatment as a Woleaian variety, while island identity supports the name Lamotrekese. The two descriptions answer different linguistic and social questions.</p>"},
      {id:"carolinian",title:"Contribution to Saipan Carolinian",html:"<p>Lamotrekese migration contributed words, pronunciations, and speakers to the emerging Refaluwasch language on Saipan. Saipan Carolinian later developed as a separate mixed community language.</p>"},
      {id:"navigation",title:"Navigation vocabulary",html:"<p>Specialized terms identify stars, swell patterns, reefs, winds, canoe parts, routes, and expected island signs. Vocabulary is transmitted with practical apprenticeship and route recitation.</p>"},
      {id:"writing",title:"Writing",html:"<p>Latin spelling appears in religious texts, correspondence, recordings, and linguistic notes. Japanese scripts dominate formal schooling and public administration.</p>"},
      {id:"contact",title:"Contact languages",html:"<p>Woleaian, Satawalese, Carolinian, and Japanese influence modern speech. Japanese supplies most vocabulary for government, medicine, engines, schooling, and paid work.</p>"},
      {id:"preservation",title:"Documentation and teaching",html:"<p>Word lists, elder recordings, route knowledge, stories, hymns, and community lessons support preservation. Materials must represent Lamotrek speech rather than silently replacing it with a regional Woleaian standard.</p>"},
      {id:"1985",title:"Status in 1985",html:"<p>By 1985 Lamotrekese remains actively spoken but is vulnerable because its population is small and dispersed. Japanese-first education and convergence with larger related languages place pressure on distinct local forms.</p>"}
    ],
    related:[{href:"lamotrekese-people.html",kicker:"Speaker community",label:"Lamotrekese People"},{href:"lamotrek.html",kicker:"Language homeland",label:"Lamotrek"},{href:"woleaian-language.html",kicker:"Broader language continuum",label:"Woleaian Language"},{href:"satawalese-language.html",kicker:"Eastern relative",label:"Satawalese Language"},{href:"carolinian-language.html",kicker:"Marianas descendant",label:"Carolinian Language"},{href:"micronesian-languages.html",kicker:"Language family",label:"Micronesian Languages"}],
    facts:[["Homeland","Lamotrek Atoll"],["Family","Austronesian"],["Branch","Oceanic · Nuclear Micronesian · Chuukic"],["Common linguistic classification","Woleaian variety"],["Community designation","Lamotrekese"],["Important descendant","Saipan Carolinian"],["Principal public counterpart","Japanese"],["1985 condition","Vulnerable"]],
    sources:[{href:"https://en.wikipedia.org/wiki/Woleaian_language",label:"Linguistic reference — Woleaian and related varieties"},{href:"https://boristheses.unibe.ch/2517/1/19kuske_e_1_.pdf",label:"University of Bern — Lamotrekese contribution to Saipan Carolinian"}]
  }),

  "ifalik":westernIslandArticle({
    title:"Ifalik",infoboxKicker:"Atoll of the Yap outer islands",
    lead:"Ifalik is a small coral atoll in the central Caroline Islands administered through Japan's Yap district. Its lagoon, four principal islets, Woleaian-related language, chiefly order, dense kinship, sharing rules, and reputation for restrained conflict make it one of the best-documented outer-island societies of Micronesia.",
    canon:"Ifalik's geography, four-islet form, Woleaian-related speech, subsistence, hierarchy, sharing ethic, and ethnographic record are historical. Continuous Japanese administration and nationality follow setting canon. Exact 1985 population, chiefs, municipal organization, transport, and public facilities remain open.",
    sections:[
      {id:"geography",title:"Geography",html:"<p>Ifalik is a low coral atoll formed by four main islets around a lagoon. Reef passages, taro pits, breadfruit land, coconut stands, wells, beaches, and fishing grounds form a tightly managed resource system.</p>"},
      {id:"settlement",title:"Settlement and livelihood",html:"<p>Residents combine gardening, lagoon and ocean fishing, canoe work, preserved food, copra, and exchange. Households depend on shared labor because storms or illness can quickly exceed one family's capacity.</p>"},
      {id:"authority",title:"Authority and rank",html:"<p>Chiefs, lineage seniors, and household leaders coordinate land, labor, ceremony, and disputes. Rank carries obligations of generosity and restraint as well as authority.</p>"},
      {id:"morality",title:"Moral order and emotion",html:"<p>Ifalik social life gives explicit moral meaning to compassion, fear, shame, and justified anger. Quiet speech, sharing, reputation, and anticipation of communal reaction limit violence without implying that disagreement is absent.</p>"},
      {id:"navigation",title:"Inter-island connections",html:"<p>Canoe routes connect Ifalik to Woleai, Eauripik, Lamotrek, Yap, and other central-Caroline islands. Marriage, tribute history, aid, and travel situate the atoll within a regional network.</p>"},
      {id:"colonial",title:"Colonial administration",html:"<p>Spanish claims, German government, and Japanese rule introduced missions, schools, copra trade, surveys, health visits, and district law. Administrative contact remained intermittent compared with the settler centers.</p>"},
      {id:"change",title:"Continuity and change",html:"<p>Japanese schooling, wage migration, radio, imported goods, and church institutions alter daily expectations. Land, sharing, chiefs, local language, fishing, and family obligations continue to organize island life.</p>"},
      {id:"1985",title:"Ifalik in 1985",html:"<p>By 1985 Ifalik is an incorporated Japanese atoll whose residents possess national citizenship. Its small scale and distance preserve strong local institutions while making transport, medicine, and education dependent on the wider empire.</p>"}
    ],
    related:[{href:"ifalik-people.html",kicker:"Island community",label:"Ifalik People"},{href:"ifalik-language.html",kicker:"Island speech",label:"Ifalik Language"},{href:"yap-islands.html",kicker:"Administrative district",label:"Yap Islands"},{href:"woleaian-people.html",kicker:"Broader cultural region",label:"Woleaian People"},{href:"lamotrek.html",kicker:"Eastern neighbor",label:"Lamotrek"},{href:"caroline-islands.html",kicker:"Regional setting",label:"Caroline Islands"}],
    facts:[["Island type","Coral atoll"],["Principal islets","Four"],["Region","Central Caroline Islands"],["Japanese district","Yap"],["Language tradition","Ifalik or Woleaian"],["Social emphasis","Sharing, restraint, and ranked authority"],["Major livelihood","Gardening and fishing"],["Nationality in 1985","Japanese"]],
    sources:[{href:"https://ehrafworldcultures.yale.edu/cultures/or21/documents/050",label:"Yale eHRAF — Ifaluk Atoll ethnographic account"},{href:"https://peacefulsocieties.uncg.edu/societies/ifaluk/",label:"UNC Greensboro — Ifalik society"}]
  }),
  "ifalik-people":westernIslandArticle({
    title:"Ifalik people",category:"Peoples of Imperial Japan",eyebrow:"Outer-island society · Empire of Japan",infoboxKicker:"Indigenous people of Ifalik",
    lead:"The Ifalik people are the indigenous people of Ifalik Atoll in the Yap outer islands. Their society is organized through kinship, rank, chiefs, land and reef rights, reciprocal sharing, restrained public conduct, and a Woleaian-related speech tradition. Their reputation as a peaceful society reflects institutions for controlling conflict rather than an absence of anger or coercion.",
    canon:"Ifalik identity, chiefly hierarchy, kinship, sharing, emotional concepts, conflict restraint, subsistence, and regional relations are historical. Japanese nationality follows setting canon. Exact 1985 population, titleholders, clan terminology, churches, and migration totals remain open.",
    sections:[
      {id:"homeland",title:"Atoll community",html:"<p>Ifalik identity begins with inherited relationships to islets, gardens, reef passages, wells, canoe beaches, and fishing grounds. Migrants remain connected through kinship and rights in the atoll.</p>"},
      {id:"kinship",title:"Kinship and rank",html:"<p>Lineages, households, adoption, marriage, seniority, and chiefly rank allocate rights and duties. Authority is personal and relational rather than merely an office created by colonial law.</p>"},
      {id:"sharing",title:"Sharing and subsistence",html:"<p>Food, labor, canoes, shelter, and assistance circulate through structured reciprocity. Generosity protects households against storms and shortages while establishing moral standing.</p>"},
      {id:"emotion",title:"Emotion and moral conduct",html:"<p>Compassion and justified anger carry public moral force. Gossip, fear of retaliation, shame, quiet speech, apology, and mediation encourage restraint but can also reinforce hierarchy.</p>"},
      {id:"conflict",title:"Conflict management",html:"<p>Community pressure favors avoidance, negotiation, compensation, and controlled expression over open violence. This system manages conflict; it does not prove that domination, resentment, or disputes are unknown.</p>"},
      {id:"regional",title:"Regional relations",html:"<p>Marriage, navigation, exchange, and the older sawei order connect Ifalik with Woleai, Yap, Lamotrek, and neighboring islands. Regional similarity coexists with a distinct Ifalik identity.</p>"},
      {id:"japanese",title:"Japanese citizenship",html:"<p>Japanese schools, shipping, health services, copra markets, and district administration expand opportunities and dependence. Ifalik people enter imperial institutions without abandoning local obligations.</p>"},
      {id:"1985",title:"Ifalik identity in 1985",html:"<p>By 1985 Ifalik people are Japanese citizens and a small, strongly localized community. Language, rank, kinship, land, sharing, moral expectations, and migration networks define peoplehood.</p>"}
    ],
    related:[{href:"ifalik.html",kicker:"Island homeland",label:"Ifalik"},{href:"ifalik-language.html",kicker:"Community speech",label:"Ifalik Language"},{href:"woleaian-people.html",kicker:"Broader cultural neighbors",label:"Woleaian People"},{href:"lamotrekese-people.html",kicker:"Eastern neighbors",label:"Lamotrekese People"},{href:"yapese-people.html",kicker:"Main-island relationship",label:"Yapese People"},{href:"micronesian-peoples.html",kicker:"Regional comparison",label:"Micronesian Peoples"}],
    facts:[["Homeland","Ifalik Atoll"],["Administrative region","Yap outer islands"],["Language tradition","Ifalik or Woleaian"],["Political tradition","Chiefly and ranked authority"],["Moral emphasis","Sharing and restraint"],["Historic regional system","Sawei"],["Principal public language","Japanese"],["Nationality in 1985","Japanese"]],
    sources:[{href:"https://ehrafworldcultures.yale.edu/cultures/or21/documents/050",label:"Yale eHRAF — Ifalik society"},{href:"https://peacefulsocieties.uncg.edu/archive/morality-domination-and-understandings-of-justifiable-anger-among-the-ifaluk/",label:"UNC Greensboro — morality and justified anger on Ifalik"}]
  }),
  "ifalik-language":westernIslandArticle({
    title:"Ifalik language",category:"Languages",eyebrow:"Chuukic variety · Ifalik Atoll",infoboxKicker:"Traditional speech of Ifalik",
    lead:"Ifalik is the traditional Chuukic speech of Ifalik Atoll. It is generally classified as a variety of Woleaian within a central-Caroline dialect continuum, but it carries island-specific vocabulary for rank, emotion, land, reef, sharing, and social conduct. Japanese is the language of higher administration and education.",
    canon:"Ifalik's Woleaian classification, local vocabulary, emotional terminology, oral transmission, and small speaker base are historical. Continuous Japanese public dominance follows setting canon. Exact 1985 speakers, separate-language recognition, orthography, school use, and vitality label remain open.",
    sections:[
      {id:"classification",title:"Classification",html:"<p>Ifalik speech belongs to the Chuukic branch of Nuclear Micronesian and is commonly classified under Woleaian. Neighboring varieties form gradual boundaries rather than sharp linguistic frontiers.</p>"},
      {id:"identity",title:"Community designation",html:"<p>Islanders recognize characteristic Ifalik pronunciation and vocabulary even when using a broader Woleaian language name. Local speech marks origin, relationship, and appropriate social conduct.</p>"},
      {id:"emotion",title:"Moral and emotional vocabulary",html:"<p>Terms for compassion, justified anger, fear, shame, restraint, and care encode judgments about social behavior. Translation into a single Japanese word often loses their relational meaning.</p>"},
      {id:"rank",title:"Respect and rank",html:"<p>Address, reference, silence, indirectness, and choice of vocabulary respond to seniority and chiefly rank. Competent speech therefore requires social knowledge as well as grammar.</p>"},
      {id:"writing",title:"Writing",html:"<p>Latin spelling appears in recordings, religious material, correspondence, and linguistic work. Japanese scripts dominate school and administration, while Woleaian standards may be used in regional material.</p>"},
      {id:"contact",title:"Language contact",html:"<p>Woleaian, Yapese, neighboring Chuukic varieties, and Japanese shape modern vocabulary. Japanese supplies terms for medicine, machinery, government, education, and paid employment.</p>"},
      {id:"preservation",title:"Documentation and teaching",html:"<p>Stories, conversations, emotional vocabulary, genealogies, songs, place names, and elder recordings preserve the local form. Documentation avoids treating social concepts as exotic words detached from their use.</p>"},
      {id:"1985",title:"Status in 1985",html:"<p>By 1985 Ifalik speech remains strong on the home atoll but vulnerable as a distinct variety. Migration, Japanese schooling, and standardization toward broader Woleaian narrow its most local forms.</p>"}
    ],
    related:[{href:"ifalik-people.html",kicker:"Speaker community",label:"Ifalik People"},{href:"ifalik.html",kicker:"Language homeland",label:"Ifalik"},{href:"woleaian-language.html",kicker:"Broader classification",label:"Woleaian Language"},{href:"lamotrekese-language.html",kicker:"Eastern related variety",label:"Lamotrekese Language"},{href:"micronesian-languages.html",kicker:"Language family",label:"Micronesian Languages"},{href:"japanese-preservationism.html",kicker:"Language policy",label:"Japanese Preservationism"}],
    facts:[["Homeland","Ifalik Atoll"],["Family","Austronesian"],["Branch","Oceanic · Nuclear Micronesian · Chuukic"],["Common classification","Woleaian variety"],["Distinctive domains","Emotion, rank, sharing, land, and reef"],["Scripts","Latin and Japanese"],["Principal public counterpart","Japanese"],["1985 condition","Strong locally; distinct variety vulnerable"]],
    sources:[{href:"https://ehrafworldcultures.yale.edu/cultures/or21/documents/050",label:"Yale eHRAF — Ifalik language in social context"},{href:"https://peacefulsocieties.uncg.edu/archive/morality-domination-and-understandings-of-justifiable-anger-among-the-ifaluk/",label:"UNC Greensboro — Ifalik moral vocabulary"}]
  }),

  "sonsorol":westernIslandArticle({
    title:"Sonsorol",eyebrow:"Southwest Islands · Palau district",infoboxKicker:"Principal island of the Sonsorol group",
    lead:"Sonsorol, known locally as Dongosaro, is the principal island of Japan's remote Sonsorol group southwest of the main Palau archipelago. Together with Fanna, Pulo Anna, and Merir, it forms a Chuukic-speaking island region culturally closer to the Yap outer islands than to Palauan-speaking Babeldaob and Koror.",
    canon:"Sonsorol's local name, four-island group, Chuukic culture, settlement traditions, Japanese-era fishing and military activity, and migration to Koror are historical. Continued Japanese administration and nationality follow setting canon. Exact 1985 population, district boundaries, garrison legacy, port works, and local offices remain open.",
    sections:[
      {id:"geography",title:"Geography",html:"<p>Dongosaro is a small sandy coral island with no large lagoon or high interior. Fanna lies nearby, while Pulo Anna and Merir extend the island chain across a broad reach of ocean.</p>"},
      {id:"settlement",title:"Settlement tradition",html:"<p>Oral histories remember founding voyagers arriving from the northeast and adapting central-Caroline practices to isolated islands. Separate traditions attach ancestry and rights to Dongosaro, Pulo Anna, Merir, and Fanna.</p>"},
      {id:"livelihood",title:"Island livelihood",html:"<p>Coconut, taro, fishing, turtles, seabirds, canoe travel, food preservation, and imported supplies support settlement. Distance and small land area make drought, storm damage, and transport failures especially dangerous.</p>"},
      {id:"difference",title:"Relation to Palau",html:"<p>Sonsorol belongs administratively to the Palau district but is not culturally Palauan. Its language and many customary connections point toward the outer islands of Yap and the wider Chuukic continuum.</p>"},
      {id:"japanese",title:"Japanese-era development",html:"<p>Japanese rule introduced regular administration, schools, fishing ventures, processing works, surveys, shipping, and strategic installations. Wartime garrisoning placed heavy demands on food and local space.</p>"},
      {id:"koror",title:"Migration to Koror",html:"<p>Education, medicine, work, and shipping encouraged families to settle around Koror. Concentrated migrant neighborhoods became vital to language and community survival as the home islands lost residents.</p>"},
      {id:"environment",title:"Environment and access",html:"<p>Reefs, beaches, vegetation, wells, and marine resources require close management. Conservation cannot be separated from the customary rights of people whose ordinary residence may be in Koror.</p>"},
      {id:"1985",title:"Sonsorol in 1985",html:"<p>By 1985 Sonsorol is a remote incorporated island within Japanese Micronesia. Its political dependence on Koror coexists with a distinct Dongosaro identity, language, and four-island historical geography.</p>"}
    ],
    related:[{href:"sonsorolese-people.html",kicker:"Island community",label:"Sonsorolese People"},{href:"sonsorolese-language.html",kicker:"Island language",label:"Sonsorolese Language"},{href:"tobi-island.html",kicker:"Southern neighbor",label:"Tobi Island"},{href:"palau-islands.html",kicker:"Administrative region",label:"Palau Islands"},{href:"koror.html",kicker:"Migration center",label:"Koror"},{href:"caroline-islands.html",kicker:"Cultural region",label:"Caroline Islands"}],
    facts:[["Local name","Dongosaro"],["Island type","Small coral island"],["Associated islands","Fanna, Pulo Anna, and Merir"],["Administrative district","Palau"],["Language","Sonsorolese"],["Cultural alignment","Chuukic outer-island"],["Major migration center","Koror"],["Nationality in 1985","Japanese"]],
    sources:[{href:"https://www.sonsorol.com/history/",label:"Sonsorol community history — islands, settlement, and culture"},{href:"https://www.palau.emb-japan.go.jp/itpr_en/11_000001_01888.html",label:"Embassy of Japan in Palau — Sonsorol history and community"}]
  }),
  "sonsorolese-people":westernIslandArticle({
    title:"Sonsorolese people",category:"Peoples of Imperial Japan",eyebrow:"Southwest-Island society · Empire of Japan",infoboxKicker:"Indigenous people of the Sonsorol group",
    lead:"The Sonsorolese people are the indigenous people of Dongosaro, Pulo Anna, Merir, and Fanna in the Southwest Islands of the Palau district. They speak a Chuukic language unrelated to Palauan and maintain island-specific dialects, fishing knowledge, kinship, oral history, and a large migrant community around Koror.",
    canon:"Sonsorolese identity, four-island homeland, distinct culture from main-island Palauans, Chuukic linguistic ties, subsistence, Japanese-era industry, and Koror migration are historical. Japanese nationality follows setting canon. Exact 1985 population, chiefs, clan system, home-island residence, and migrant institutions remain open.",
    sections:[
      {id:"homeland",title:"Four-island homeland",html:"<p>Sonsorolese ancestry and rights attach to Dongosaro, Pulo Anna, Merir, and Fanna. Each island has its own settlement memories and speech forms within a shared peoplehood.</p>"},
      {id:"origins",title:"Origins and regional ties",html:"<p>Oral histories trace founding voyages from the northeast. Language and material culture connect the people to Tobi and the outer Carolines more closely than to Palauan-speaking main islands.</p>"},
      {id:"society",title:"Kinship and authority",html:"<p>Families, descent, adoption, marriage, seniority, and island leadership organize land, work, fishing, travel, and mutual assistance. Migration extends rather than dissolves these relationships.</p>"},
      {id:"sea",title:"Sea knowledge",html:"<p>Fishing, canoe handling, reefs, currents, weather, turtles, birds, and routes form a practical body of island knowledge. Small populations make teaching and cooperative work essential.</p>"},
      {id:"japanese",title:"Japanese rule",html:"<p>Schools, commercial fishing, processing, shipping, surveys, medicine, and wartime forces brought Japanese institutions into the Southwest Islands. Islanders remained unequal but acquired national citizenship after permanent incorporation.</p>"},
      {id:"koror",title:"Koror community",html:"<p>Most opportunities in education, medicine, and employment lie in Koror. A concentrated Sonsorolese neighborhood allows language, food, marriage, church, and island associations to continue away from the home islands.</p>"},
      {id:"identity",title:"Sonsorolese and Palauan identities",html:"<p>Administrative membership in the Palau district encourages Palauan bilingualism and intermarriage. Sonsorolese identity persists through language, ancestry, island rights, and Southwest-Island history.</p>"},
      {id:"1985",title:"Sonsorolese identity in 1985",html:"<p>By 1985 Sonsorolese are Japanese citizens and one of the empire's smallest distinct peoples. Their survival depends on connecting the Koror diaspora to sparsely inhabited home islands.</p>"}
    ],
    related:[{href:"sonsorol.html",kicker:"Principal home island",label:"Sonsorol"},{href:"sonsorolese-language.html",kicker:"Ancestral language",label:"Sonsorolese Language"},{href:"tobian-people.html",kicker:"Closest southern neighbors",label:"Tobian People"},{href:"palauan-people.html",kicker:"Main-island neighbors",label:"Palauan People"},{href:"koror.html",kicker:"Diaspora center",label:"Koror"},{href:"micronesian-peoples.html",kicker:"Regional comparison",label:"Micronesian Peoples"}],
    facts:[["Homeland","Dongosaro, Pulo Anna, Merir, and Fanna"],["Language","Sonsorolese"],["Language family","Chuukic"],["Distinct from","Palauan people and language"],["Closest southern neighbors","Tobian people"],["Major diaspora","Koror"],["Principal public language","Japanese"],["Nationality in 1985","Japanese"]],
    sources:[{href:"https://www.sonsorol.com/history/",label:"Sonsorol community history — people and culture"},{href:"https://www.palau.emb-japan.go.jp/files/100824764.pdf",label:"Embassy of Japan in Palau — people of Sonsorol"}]
  }),
  "sonsorolese-language":westernIslandArticle({
    title:"Sonsorolese language",category:"Languages",eyebrow:"Chuukic language · Southwest Islands",infoboxKicker:"Indigenous language of the Sonsorol group",
    lead:"Sonsorolese, locally called <em>ramari Dongosaro</em>, is the Chuukic language of Dongosaro, Pulo Anna, and Merir. It is unrelated to Palauan despite administration through the Palau district and is closely related to Tobian and the outer-island languages of Yap. Japanese and Palauan dominate many public and migrant domains.",
    canon:"Sonsorolese classification, Dongosaro name, island dialects, distinction from Palauan, close relation to Tobian and Woleaian, and Koror diaspora are historical. Continuous Japanese dominance and the absence of an English trusteeship follow setting canon. Exact 1985 speakers, legal status, orthography, and vitality category remain open.",
    sections:[
      {id:"classification",title:"Classification",html:"<p>Sonsorolese belongs to the Chuukic branch of Nuclear Micronesian. Its closest major relative is Tobian, with wider connections to Woleaian and other Yap outer-island languages.</p>"},
      {id:"name",title:"Name",html:"<p><em>Ramari Dongosaro</em> identifies the language of Dongosaro. Sonsorolese remains common in Japanese administration and regional scholarship.</p>"},
      {id:"dialects",title:"Island dialects",html:"<p>Dongosaro, Pulo Anna, and Merir possess distinct pronunciation and vocabulary. Migration and depopulation bring the forms into closer contact around Koror.</p>"},
      {id:"tobian",title:"Relationship to Tobian",html:"<p>Tobian is closely related but historically distinct. Co-residence, intermarriage, and bilingualism in Koror increasingly reduce differences without erasing separate island identities.</p>"},
      {id:"writing",title:"Writing",html:"<p>Latin spelling supports dictionaries, community websites, invitations, recordings, and teaching materials. Japanese scripts govern formal education and administration.</p>"},
      {id:"contact",title:"Japanese and Palauan contact",html:"<p>Japanese supplies public and technical vocabulary, while Palauan is common in Koror commerce and intermarriage. Younger migrant speech often mixes all three languages.</p>"},
      {id:"revival",title:"Documentation and teaching",html:"<p>Community dictionaries, recordings, dialect notes, stories, lessons, and island histories support revitalization. Materials give separate attention to Pulo Anna and Merir forms before they disappear.</p>"},
      {id:"1985",title:"Status in 1985",html:"<p>By 1985 Sonsorolese is endangered because the population is very small and concentrated away from its home islands. A dense Koror community provides the strongest opportunity for intergenerational transmission.</p>"}
    ],
    related:[{href:"sonsorolese-people.html",kicker:"Speaker community",label:"Sonsorolese People"},{href:"sonsorol.html",kicker:"Principal homeland",label:"Sonsorol"},{href:"tobian-language.html",kicker:"Closest major relative",label:"Tobian Language"},{href:"woleaian-language.html",kicker:"Regional relative",label:"Woleaian Language"},{href:"palauan-language.html",kicker:"District contact language",label:"Palauan Language"},{href:"micronesian-languages.html",kicker:"Language family",label:"Micronesian Languages"}],
    facts:[["Native name","ramari Dongosaro"],["Homeland","Dongosaro, Pulo Anna, and Merir"],["Family","Austronesian"],["Branch","Oceanic · Nuclear Micronesian · Chuukic"],["Principal dialects","Dongosaro, Pulo Anna, and Merir"],["Closest major relative","Tobian"],["Principal public counterpart","Japanese"],["1985 condition","Endangered"]],
    sources:[{href:"https://www.sonsorol.com/language/",label:"Sonsorol community language reference"},{href:"https://en.wikipedia.org/wiki/Sonsorolese",label:"Linguistic reference — Sonsorolese"}]
  }),

  "tobi-island":westernIslandArticle({
    title:"Tobi Island",eyebrow:"Southwest Islands · Palau district",infoboxKicker:"Home island of the Tobian people",
    lead:"Tobi Island, locally Hatohobei, is the southernmost inhabited island of the Japanese Palau district and the homeland of the Tobian people. The small coral island and nearby Helen Reef form an isolated jurisdiction whose Chuukic language and culture are more closely connected to Sonsorol and the Yap outer islands than to main-island Palau.",
    canon:"Tobi's Hatohobei name, geography, Helen Reef relationship, Chuukic culture, settlement traditions, colonial history, archaeology, and migration to Koror are historical. Continued Japanese administration follows setting canon. Exact 1985 population, reef station, district status, officials, and transport remain open.",
    sections:[
      {id:"geography",title:"Geography",html:"<p>Hatohobei is a low coral island in the far southwest of the Palau district. Helen Reef lies farther east and gives the community an enormous maritime geography compared with its tiny land area.</p>"},
      {id:"settlement",title:"Settlement history",html:"<p>Oral traditions and archaeology record settlement by voyagers connected to the central Caroline world. Isolation allowed a distinct Tobian language and island identity to develop.</p>"},
      {id:"livelihood",title:"Island livelihood",html:"<p>Coconut, taro, fishing, turtles, seabirds, canoe work, preserved food, and imported supplies sustain settlement. Freshwater and storm damage impose severe limits.</p>"},
      {id:"helen",title:"Helen Reef",html:"<p>Helen Reef provides fishing grounds, navigation points, ecological value, and a large maritime claim. Access and conservation depend on Tobian knowledge as well as Japanese patrol capacity.</p>"},
      {id:"relation",title:"Relation to Palau and Sonsorol",html:"<p>Tobi is administered with Palau but differs linguistically from Palauan-speaking islands. Tobian culture and speech are closest to Sonsorolese and the outer-Caroline continuum.</p>"},
      {id:"colonial",title:"Colonial administration",html:"<p>Spanish claims, German rule, and Japanese administration introduced surveys, schools, medicine, shipping, fishing ventures, and strategic oversight. The island remained remote from Koror's settler society.</p>"},
      {id:"migration",title:"Migration to Koror",html:"<p>Education, health care, work, and transport draw most Tobian families toward Koror. Home-island rights, reef responsibility, language, and community associations continue despite low permanent residence.</p>"},
      {id:"1985",title:"Tobi in 1985",html:"<p>By 1985 Hatohobei is an incorporated Japanese island and symbolic center of a much larger maritime territory. Its continuing existence depends on maintaining both a small resident presence and a vigorous Koror diaspora.</p>"}
    ],
    related:[{href:"tobian-people.html",kicker:"Island community",label:"Tobian People"},{href:"tobian-language.html",kicker:"Island language",label:"Tobian Language"},{href:"sonsorol.html",kicker:"Northern neighbor",label:"Sonsorol"},{href:"palau-islands.html",kicker:"Administrative region",label:"Palau Islands"},{href:"koror.html",kicker:"Migration center",label:"Koror"},{href:"caroline-islands.html",kicker:"Cultural region",label:"Caroline Islands"}],
    facts:[["Local name","Hatohobei"],["Island type","Small coral island"],["Associated reef","Helen Reef"],["Position","Southernmost inhabited island of the Palau district"],["Indigenous community","Tobian"],["Language","Tobian"],["Major migration center","Koror"],["Nationality in 1985","Japanese"]],
    sources:[{href:"https://en.wikipedia.org/wiki/Hatohobei",label:"Geographic reference — Hatohobei"},{href:"https://www.palau.emb-japan.go.jp/itpr_en/11_000001_01995.html",label:"Embassy of Japan in Palau — Hatohobei community"},{href:"https://www.jstage.jst.go.jp/article/jsos/22/0/22_53/_pdf",label:"Archaeological research on Tobi Island"}]
  }),
  "tobian-people":westernIslandArticle({
    title:"Tobian people",category:"Peoples of Imperial Japan",eyebrow:"Southwest-Island society · Empire of Japan",infoboxKicker:"Indigenous people of Hatohobei",
    lead:"The Tobian people are the indigenous people of Tobi Island, or Hatohobei, and the customary community associated with Helen Reef. Their Chuukic language, fishing and reef knowledge, island ancestry, kinship, and migrant community around Koror distinguish them from both Palauans and the closely related Sonsorolese.",
    canon:"Tobian identity, Hatohobei homeland, Helen Reef ties, Chuukic linguistic relationship, subsistence, cultural difference from Palauans, and Koror migration are historical. Japanese nationality follows setting canon. Exact 1985 population, leaders, land and reef tenure, resident numbers, and associations remain open.",
    sections:[
      {id:"homeland",title:"Hatohobei homeland",html:"<p>Tobian ancestry connects families to a very small island and a vast surrounding sea. House sites, gardens, beaches, reefs, fishing grounds, and Helen Reef carry practical and historical rights.</p>"},
      {id:"origins",title:"Origins and distinct identity",html:"<p>Settlement traditions connect Hatohobei to voyagers from the wider Caroline world. Long isolation produced a people and language distinct from neighboring Sonsorol and main-island Palau.</p>"},
      {id:"society",title:"Kinship and authority",html:"<p>Family, descent, adoption, marriage, seniority, and island leadership organize land, work, aid, and representation. A person may remain fully Tobian while living most of the year in Koror.</p>"},
      {id:"reef",title:"Sea and reef knowledge",html:"<p>Fishing, currents, weather, species, reef passages, canoe handling, and distant travel form a central body of knowledge. Helen Reef makes conservation and patrol questions part of ordinary Tobian politics.</p>"},
      {id:"japanese",title:"Japanese rule",html:"<p>Schools, health services, fishing, surveys, shipping, and administration linked Hatohobei to Koror and Japan. Remoteness limited settler residence while increasing dependence on official transport.</p>"},
      {id:"diaspora",title:"Koror diaspora",html:"<p>Most education, medicine, employment, and marriage opportunities lie around Koror. A concentrated Southwest-Island neighborhood supports Tobian language and intermarriage with Sonsorolese families.</p>"},
      {id:"preservation",title:"Cultural teaching",html:"<p>Women's associations, elders, fishermen, language workers, and return visits teach weaving, taro cultivation, cooking, fishing, stories, and island history. Preservation joins practical skills to continued access.</p>"},
      {id:"1985",title:"Tobian identity in 1985",html:"<p>By 1985 Tobians are Japanese citizens and one of the empire's smallest peoples. Peoplehood survives through Hatohobei ancestry, language, Helen Reef responsibility, and a diaspora able to sustain a permanent island connection.</p>"}
    ],
    related:[{href:"tobi-island.html",kicker:"Island homeland",label:"Tobi Island"},{href:"tobian-language.html",kicker:"Ancestral language",label:"Tobian Language"},{href:"sonsorolese-people.html",kicker:"Closest neighboring people",label:"Sonsorolese People"},{href:"palauan-people.html",kicker:"Main-island neighbors",label:"Palauan People"},{href:"koror.html",kicker:"Diaspora center",label:"Koror"},{href:"micronesian-peoples.html",kicker:"Regional comparison",label:"Micronesian Peoples"}],
    facts:[["Self-designation of homeland","Hatohobei"],["Homeland","Tobi Island and Helen Reef"],["Language","Tobian"],["Language family","Chuukic"],["Distinct from","Palauan and Sonsorolese peoples"],["Major diaspora","Koror"],["Principal public language","Japanese"],["Nationality in 1985","Japanese"]],
    sources:[{href:"https://www.palau.emb-japan.go.jp/itpr_en/11_000001_01995.html",label:"Embassy of Japan in Palau — Hatohobei people and cultural teaching"},{href:"https://www.friendsoftobi.org/misc/research/hoseiruraleducationpalau2002.pdf",label:"Friends of Tobi — Tobian education and cultural identity"}]
  }),
  "tobian-language":westernIslandArticle({
    title:"Tobian language",category:"Languages",eyebrow:"Chuukic language · Hatohobei",infoboxKicker:"Indigenous language of Tobi Island",
    lead:"Tobian, locally <em>ramarih Hatohobei</em>, is the Chuukic language of Tobi Island and its diaspora around Koror. It is closely related to Sonsorolese and the outer-island languages of Yap but is unrelated to Palauan. Migration and intermarriage bring Tobian and Sonsorolese closer while placing both under strong Japanese and Palauan pressure.",
    canon:"Tobian's native name, Chuukic classification, close but distinct relationship to Sonsorolese, difference from Palauan, and Koror diaspora are historical. Continuous Japanese dominance and the absence of an English trusteeship follow setting canon. Exact 1985 speakers, orthography, school program, and vitality category remain open.",
    sections:[
      {id:"classification",title:"Classification",html:"<p>Tobian belongs to the Chuukic branch of Nuclear Micronesian. It is closest to Sonsorolese and shares wider features with Woleaian and other Yap outer-island languages.</p>"},
      {id:"name",title:"Native name",html:"<p><em>Ramarih Hatohobei</em> means the language of Tobi. Tobian remains the common Japanese and international designation.</p>"},
      {id:"sonsorolese",title:"Relationship to Sonsorolese",html:"<p>Tobian and Sonsorolese are closely related but historically not fully interchangeable. Co-residence and intermarriage in Koror increasingly level distinctive vocabulary and pronunciation.</p>"},
      {id:"palauan",title:"Distinction from Palauan",html:"<p>Geographic administration does not determine linguistic ancestry. Palauan belongs to a separate western Malayo-Polynesian line and is not a parent language of Tobian.</p>"},
      {id:"writing",title:"Writing",html:"<p>Latin spelling is used in dictionaries, recordings, community messages, and lessons. Japanese scripts dominate formal education and government.</p>"},
      {id:"contact",title:"Contact and migration",html:"<p>Japanese supplies public and technical vocabulary, while Palauan is common in Koror commerce. Sonsorolese influences younger Tobian speech through shared neighborhoods and families.</p>"},
      {id:"revival",title:"Revitalization",html:"<p>Recordings, community classes, school projects, fishing vocabulary, oral histories, and digital media support the language. Work distinguishes fluent elder speech from newer Sonsorolese-convergent forms.</p>"},
      {id:"1985",title:"Status in 1985",html:"<p>By 1985 Tobian is definitely endangered. The home-island population is very small, most speakers live in a multilingual Koror environment, and only active teaching can preserve its distinct form.</p>"}
    ],
    related:[{href:"tobian-people.html",kicker:"Speaker community",label:"Tobian People"},{href:"tobi-island.html",kicker:"Language homeland",label:"Tobi Island"},{href:"sonsorolese-language.html",kicker:"Closest major relative",label:"Sonsorolese Language"},{href:"woleaian-language.html",kicker:"Regional relative",label:"Woleaian Language"},{href:"palauan-language.html",kicker:"District contact language",label:"Palauan Language"},{href:"micronesian-languages.html",kicker:"Language family",label:"Micronesian Languages"}],
    facts:[["Native name","ramarih Hatohobei"],["Homeland","Tobi Island"],["Family","Austronesian"],["Branch","Oceanic · Nuclear Micronesian · Chuukic"],["Closest major relative","Sonsorolese"],["Major diaspora","Koror"],["Principal public counterpart","Japanese"],["1985 condition","Definitely endangered"]],
    sources:[{href:"https://en.wikipedia.org/wiki/Tobian_language",label:"Linguistic reference — Tobian language"},{href:"https://www.friendsoftobi.org/misc/research/hoseiruraleducationpalau2002.pdf",label:"Friends of Tobi — language and education"},{href:"https://www.youtube.com/watch?v=VCxeM27OAlQ",label:"Wikitongues — Tobian speech sample"}]
  })
});

